Dataspatium.assets.register("presets/api/smhi-metobs.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"smhi-metobs\",\n  \"name\": \"SMHI meteorologiska observationer\",\n  \"publisher\": \"SMHI\",\n  \"description\": \"Mätvärden från SMHI:s väderstationer: temperatur, nederbörd, vind, lufttryck med mera. Välj parameter, station och tidsutsnitt. Det kvalitetskontrollerade arkivet hämtas som CSV och kan vara stort.\",\n  \"docs\": \"https://opendata.smhi.se/apidocs/metobs/index.html\",\n  \"license\": { \"name\": \"CC BY 4.0\", \"url\": \"https://creativecommons.org/licenses/by/4.0/\" },\n  \"level\": 1,\n  \"baseUrl\": \"https://opendata-download-metobs.smhi.se/api/version\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 2 },\n  \"endpoints\": [\n    {\n      \"id\": \"parameters\",\n      \"name\": \"Parametrar\",\n      \"description\": \"Alla mätparametrar med nyckel, namn och enhet.\",\n      \"method\": \"GET\",\n      \"path\": \"/1.0.json\",\n      \"response\": { \"format\": \"json\", \"path\": \"resource\", \"drop\": [\"link\"] },\n      \"dataset\": { \"name\": \"SMHI parametrar\" }\n    },\n    {\n      \"id\": \"stations\",\n      \"name\": \"Stationer för en parameter\",\n      \"method\": \"GET\",\n      \"path\": \"/1.0/parameter/{parameter}.json\",\n      \"params\": [\n        { \"name\": \"parameter\", \"in\": \"path\", \"label\": \"Parameter\", \"type\": \"string\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"parameters\", \"value\": \"key\", \"label\": \"title\" } }\n      ],\n      \"response\": { \"format\": \"json\", \"path\": \"station\", \"drop\": [\"link\", \"summary\"], \"convert\": { \"from\": \"epoch-ms\", \"to\": \"epoch-ms\", \"updated\": \"epoch-ms\" }, \"rename\": { \"key\": \"station_id\", \"name\": \"station\", \"from\": \"fran\", \"to\": \"till\", \"updated\": \"uppdaterad\", \"height\": \"hojd\", \"latitude\": \"latitud\", \"longitude\": \"longitud\", \"owner\": \"agare\", \"active\": \"aktiv\" } },\n      \"dataset\": { \"name\": \"SMHI stationer parameter {parameter}\" }\n    },\n    {\n      \"id\": \"data\",\n      \"name\": \"Mätvärden för en station\",\n      \"description\": \"Senaste timmen, dygnet eller fyra månaderna för en parameter och station. Tider i lokal tid.\",\n      \"method\": \"GET\",\n      \"path\": \"/1.0/parameter/{parameter}/station/{station}/period/{period}/data.json\",\n      \"params\": [\n        { \"name\": \"parameter\", \"in\": \"path\", \"label\": \"Parameter\", \"type\": \"string\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"parameters\", \"value\": \"key\", \"label\": \"title\" } },\n        { \"name\": \"station\", \"in\": \"path\", \"label\": \"Station\", \"type\": \"string\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"stations\", \"value\": \"station_id\", \"label\": \"station\", \"params\": { \"parameter\": \"{parameter}\" } } },\n        { \"name\": \"period\", \"in\": \"path\", \"label\": \"Tidsutsnitt\", \"type\": \"enum\", \"required\": true, \"default\": \"latest-day\", \"options\": [{ \"value\": \"latest-hour\", \"label\": \"Senaste timmen\" }, { \"value\": \"latest-day\", \"label\": \"Senaste dygnet\" }, { \"value\": \"latest-months\", \"label\": \"Senaste fyra månaderna\" }] }\n      ],\n      \"response\": { \"format\": \"json\", \"path\": \"value\", \"constants\": { \"parameter\": \"parameter.name\", \"enhet\": \"parameter.unit\", \"station\": \"station.name\", \"station_id\": \"station.key\" }, \"convert\": { \"date\": \"epoch-ms\" }, \"rename\": { \"date\": \"tid\", \"value\": \"varde\", \"quality\": \"kvalitet\" } },\n      \"dataset\": { \"name\": \"SMHI {period} station {station}\", \"keys\": [\"station_id\", \"parameter\", \"tid\"] }\n    },\n    {\n      \"id\": \"archive\",\n      \"name\": \"Kvalitetskontrollerat arkiv för en station (CSV)\",\n      \"description\": \"Hela den granskade mätserien för en parameter och station. Kan vara hundratusentals rader.\",\n      \"method\": \"GET\",\n      \"path\": \"/1.0/parameter/{parameter}/station/{station}/period/corrected-archive/data.csv\",\n      \"headers\": { \"Accept\": \"text/csv, text/plain, */*\" },\n      \"params\": [\n        { \"name\": \"parameter\", \"in\": \"path\", \"label\": \"Parameter\", \"type\": \"string\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"parameters\", \"value\": \"key\", \"label\": \"title\" } },\n        { \"name\": \"station\", \"in\": \"path\", \"label\": \"Station\", \"type\": \"string\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"stations\", \"value\": \"station_id\", \"label\": \"station\", \"params\": { \"parameter\": \"{parameter}\" } } }\n      ],\n      \"response\": { \"format\": \"csv\", \"options\": { \"delimiter\": \";\", \"skipUntil\": \"Datum;\", \"decimal\": \"point\" } },\n      \"dataset\": { \"name\": \"SMHI arkiv parameter {parameter} station {station}\" }\n    },\n    {\n      \"id\": \"latest-all\",\n      \"name\": \"Senaste timmen för alla stationer\",\n      \"description\": \"Det senaste värdet från varje station för en parameter, med position.\",\n      \"method\": \"GET\",\n      \"path\": \"/1.0/parameter/{parameter}/station-set/all/period/latest-hour/data.json\",\n      \"params\": [\n        { \"name\": \"parameter\", \"in\": \"path\", \"label\": \"Parameter\", \"type\": \"string\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"parameters\", \"value\": \"key\", \"label\": \"title\" } }\n      ],\n      \"response\": { \"format\": \"json\", \"path\": \"station\", \"explode\": \"value\", \"constants\": { \"parameter\": \"parameter.name\", \"enhet\": \"parameter.unit\" }, \"convert\": { \"date\": \"epoch-ms\", \"from\": \"epoch-ms\", \"to\": \"epoch-ms\" }, \"rename\": { \"key\": \"station_id\", \"name\": \"station\", \"date\": \"tid\", \"value\": \"varde\", \"quality\": \"kvalitet\", \"height\": \"hojd\", \"latitude\": \"latitud\", \"longitude\": \"longitud\", \"owner\": \"agare\" }, \"drop\": [\"link\", \"from\", \"to\", \"ownerCategory\", \"measuringStations\"] },\n      \"dataset\": { \"name\": \"SMHI {parameter} senaste timmen\", \"keys\": [\"station_id\", \"tid\"] }\n    }\n  ]\n}\n");
